BEGIN;
SELECT pg_advisory_xact_lock(hashtextextended('PROFILE-RECOVERY-FEES-2026-10-18-002',0));
DO $$ BEGIN IF EXISTS(SELECT 1 FROM historical_import_records WHERE source_key='PROFILE-RECOVERY-FEES-2026-10-18-002' OR source_hash='eb56e89a332661747b055d24e085c06b0191be6a4b8ab45336506fb8c2d4020e') OR EXISTS(SELECT 1 FROM operational_audit_events WHERE operation_reference='PROFILE-RECOVERY-FEES-2026-10-18-002') THEN RAISE EXCEPTION 'REFERENCE_CONSUMED'; END IF; IF (SELECT count(*) FROM drizzle.__drizzle_migrations)<>35 THEN RAISE EXCEPTION 'SCHEMA_NOT_READY'; END IF; IF EXISTS(SELECT 1 FROM production_batches) THEN RAISE EXCEPTION 'REVIEW_EXISTING_BATCHES'; END IF; IF (SELECT count(*) FROM production_profiles)<>17 OR (SELECT count(*) FROM production_profile_components)<>12 THEN RAISE EXCEPTION 'PROFILE_DRIFT'; END IF; IF NOT EXISTS(SELECT 1 FROM management_scenarios WHERE id=1 AND status='draft' AND revision=1) OR EXISTS(SELECT 1 FROM management_scenarios WHERE status='active') THEN RAISE EXCEPTION 'SCENARIO_CHANGED'; END IF; END $$;
CREATE TEMP TABLE release_before(table_name text,row_data jsonb) ON COMMIT DROP;
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename LOOP EXECUTE format('LOCK TABLE public.%I IN SHARE ROW EXCLUSIVE MODE',t.tablename); EXECUTE format('INSERT INTO pg_temp.release_before SELECT %L,to_jsonb(r) FROM public.%I r',t.tablename,t.tablename); END LOOP; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.products t) <> '5933a57611d4d1e59b86ae2958cd0fb1' THEN RAISE EXCEPTION 'SOURCE_DRIFT_products'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.recipe_items t) <> '057a21d5fadcf4e8553084ec917293c7' THEN RAISE EXCEPTION 'SOURCE_DRIFT_recipe_items'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.recipe_versions t) <> '0ee0c91aa9cf65095a0e3e60c2d9a6b8' THEN RAISE EXCEPTION 'SOURCE_DRIFT_recipe_versions'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.management_settings t) <> 'dacddc33e6a13fc7f49c82e405a382a8' THEN RAISE EXCEPTION 'SOURCE_DRIFT_management_settings'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.production_profiles t) <> '36f821827ea930fe4d9a161eaf09a624' THEN RAISE EXCEPTION 'SOURCE_DRIFT_production_profiles'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.management_scenarios t) <> '2013fad69cb7a8ca2765ec1c29d51e5f' THEN RAISE EXCEPTION 'SOURCE_DRIFT_management_scenarios'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.management_scenario_mix t) <> 'ff728c9b45196f0260de7cba45caee5c' THEN RAISE EXCEPTION 'SOURCE_DRIFT_management_scenario_mix'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.production_profile_components t) <> '7c26e5e94956ade01d3aa0d2ddab2de9' THEN RAISE EXCEPTION 'SOURCE_DRIFT_production_profile_components'; END IF; END $$;
DO $$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(t)-'created_at'-'updated_at'-'payment_fees' ORDER BY (to_jsonb(t)-'created_at'-'updated_at'-'payment_fees')::text),'[]'::jsonb)::text) FROM public.recipe_operational_requirements t) <> '2afffe68e026d98258ca7c40eb66f64f' THEN RAISE EXCEPTION 'SOURCE_DRIFT_recipe_operational_requirements'; END IF; END $$;
UPDATE products SET sale_price=6.00,description='Pacote de 100 g de massa aproveitada após o corte. Um saquinho e um adesivo.',updated_at=now() WHERE sku='PROD002';
UPDATE products SET name='Chocolate em pó Melken 50%',description=concat_ws(' / ',description,'Especificação confirmada: Melken 50% em pó; referência R$ 60/kg.'),updated_at=now() WHERE sku='INS003';
UPDATE recipe_versions SET status='archived',updated_at=now() WHERE source_id='RECIPE-BASE-001';
UPDATE management_settings SET fixed_monthly_costs=2288,payment_fees='{"debitBps":143,"creditBps":336,"pixFixedCents":49,"effectiveOn":"2026-10-18"}'::jsonb,version=version+1,updated_at=now() WHERE id=1 AND version=1;
UPDATE management_scenarios SET status='archived',revision=revision+1,archived_at=now(),archived_by_auth_user_id='codex:authorized-hml-release',archive_reason='Substituído por versão de custos e meta conjunta; histórico preservado.',updated_at=now() WHERE id=1 AND status='draft' AND revision=1;
DO $$ DECLARE t record; different boolean; BEGIN FOR t IN SELECT DISTINCT table_name FROM pg_temp.release_before WHERE table_name NOT IN ('products','recipe_versions','management_settings','management_scenarios','management_scenario_mix','recipe_items','recipe_operational_requirements','production_profiles','production_profile_components','management_scenario_history','historical_import_records','operational_audit_events') LOOP EXECUTE format('SELECT EXISTS((SELECT row_data FROM pg_temp.release_before WHERE table_name=%L EXCEPT SELECT to_jsonb(r) FROM public.%I r) UNION ALL (SELECT to_jsonb(r) FROM public.%I r EXCEPT SELECT row_data FROM pg_temp.release_before WHERE table_name=%L))',t.table_name,t.table_name,t.table_name,t.table_name) INTO different; IF different THEN RAISE EXCEPTION 'UNRELATED_TABLE_CHANGED: %',t.table_name; END IF; END LOOP; IF (SELECT count(*) FROM production_profiles WHERE recipe_version_id=(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002'))<>17 OR (SELECT count(*) FROM production_profile_components c JOIN production_profiles p ON p.id=c.production_profile_id WHERE p.recipe_version_id=(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002'))<>31 OR (SELECT count(*) FROM recipe_items WHERE recipe_version_id=(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002'))<>7 OR (SELECT sum(normalized_weight_bps) FROM management_scenario_mix WHERE scenario_id=(SELECT id FROM management_scenarios WHERE supersedes_scenario_id=1 AND version=2))<>10000 THEN RAISE EXCEPTION 'POSTCONDITION_FAILED'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='management_scenario_mix' EXCEPT SELECT to_jsonb(r) FROM public.management_scenario_mix r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_management_scenario_mix'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='recipe_items' EXCEPT SELECT to_jsonb(r) FROM public.recipe_items r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_recipe_items'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='recipe_operational_requirements' EXCEPT SELECT to_jsonb(r) FROM public.recipe_operational_requirements r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_recipe_operational_requirements'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='production_profiles' EXCEPT SELECT to_jsonb(r) FROM public.production_profiles r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_production_profiles'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='production_profile_components' EXCEPT SELECT to_jsonb(r) FROM public.production_profile_components r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_production_profile_components'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='management_scenario_history' EXCEPT SELECT to_jsonb(r) FROM public.management_scenario_history r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_management_scenario_history'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='historical_import_records' EXCEPT SELECT to_jsonb(r) FROM public.historical_import_records r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_historical_import_records'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT row_data FROM pg_temp.release_before WHERE table_name='operational_audit_events' EXCEPT SELECT to_jsonb(r) FROM public.operational_audit_events r) THEN RAISE EXCEPTION 'EXISTING_ROW_CHANGED_operational_audit_events'; END IF; END $$;
COMMIT;
