INSERT INTO products(sku,name,description,product_type,measurement_unit,category_id,is_active) SELECT 'EMB-BORDINHAS-100G','Saquinho Bordinhas 100 g','Referência confirmada: R$ 0,11/unidade. Identidade própria, sem fusão com outras embalagens.','packaging','unit',category_id,true FROM products WHERE sku='INS007';
INSERT INTO recipe_versions(source_id,source_hash,name,version,status,source_payload) SELECT 'RECIPE-BASE-002','d668e04b605f6280bc195f9be90a3415aad4a3e92f6b30405eba15b78b309f2e','Receita-base — 850 g frios',2,'active',source_payload || '{"recovery":{"mode":"weighed","bakedWeightGrams":"850.000","packWeightGrams":"100.000","operationalInput":"batch_totals"},"reference":"PROFILE-RECOVERY-FEES-2026-10-18-002","sourceRecipeId":1,"formDimensionsCm":["44","31.3","3"],"costPlanning":{"laborIncludedInFixed":true,"energyIncludedInFixed":true}}'::jsonb FROM recipe_versions WHERE source_id='RECIPE-BASE-001';
INSERT INTO recipe_items(source_key,source_hash,recipe_version_id,product_id,quantity,unit,source_name,historical_cost,source_payload) SELECT 'PROFILE-RECOVERY-FEES-2026-10-18-002:item:'||id,encode(sha256(convert_to('PROFILE-RECOVERY-FEES-2026-10-18-002:item:'||id,'UTF8')),'hex'),(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002'),product_id,quantity,unit,source_name,historical_cost,source_payload||jsonb_build_object('previousRecipeItemId',id,'reference','PROFILE-RECOVERY-FEES-2026-10-18-002') FROM recipe_items WHERE recipe_version_id=1;
INSERT INTO recipe_operational_requirements(source_key,source_hash,recipe_version_id,type,quantity,unit,historical_cost,source_payload) SELECT 'PROFILE-RECOVERY-FEES-2026-10-18-002:operational:'||type::text,encode(sha256(convert_to('PROFILE-RECOVERY-FEES-2026-10-18-002:operational:'||type::text,'UTF8')),'hex'),(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002'),type,1,'batch',NULL,jsonb_build_object('reference','PROFILE-RECOVERY-FEES-2026-10-18-002','input','explicit_total_per_batch','planningAlreadyIncludedInFixed',true) FROM recipe_operational_requirements WHERE recipe_version_id=1;
INSERT INTO production_profiles(source_id,source_hash,recipe_version_id,product_id,cut_size,filling,expected_yield,packaging_product_id,packaging_quantity,source_payload) SELECT 'RECIPE-BASE-002:'||p.sku,encode(sha256(convert_to('RECIPE-BASE-002:'||p.sku,'UTF8')),'hex'),(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002'),pr.product_id,pr.cut_size,pr.filling,CASE WHEN p.sku='PROD002' THEN 0 ELSE pr.expected_yield END,CASE p.sku WHEN 'PROD001' THEN (SELECT id FROM products WHERE sku='INS011') WHEN 'PROD002' THEN (SELECT id FROM products WHERE sku='EMB-BORDINHAS-100G') WHEN 'PROD017' THEN (SELECT id FROM products WHERE sku='INS012') ELSE pr.packaging_product_id END,1,pr.source_payload||jsonb_build_object('previousProfileId',pr.id,'reference','PROFILE-RECOVERY-FEES-2026-10-18-002','operationallyComplete',true,'limitation',NULL,'yieldBasis',CASE WHEN p.sku='PROD002' THEN 'measured_100g_packs' ELSE 'alternative_per_recipe' END) FROM production_profiles pr JOIN products p ON p.id=pr.product_id WHERE pr.recipe_version_id=1;
INSERT INTO production_profile_components(source_id,source_hash,production_profile_id,product_id,role,quantity,unit,quantity_basis,source_payload) SELECT 'PROFILE-RECOVERY-FEES-2026-10-18-002:filling:'||c.id,encode(sha256(convert_to('PROFILE-RECOVERY-FEES-2026-10-18-002:filling:'||c.id,'UTF8')),'hex'),n.id,c.product_id,c.role,c.quantity,c.unit,c.quantity_basis,c.source_payload||jsonb_build_object('previousComponentId',c.id,'reference','PROFILE-RECOVERY-FEES-2026-10-18-002') FROM production_profile_components c JOIN production_profiles old ON old.id=c.production_profile_id JOIN production_profiles n ON n.recipe_version_id=(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002') AND n.product_id=old.product_id WHERE old.recipe_version_id=1;
INSERT INTO production_profile_components(source_id,source_hash,production_profile_id,product_id,role,quantity,unit,quantity_basis,source_payload) SELECT 'PROFILE-RECOVERY-FEES-2026-10-18-002:adhesive:'||p.sku,encode(sha256(convert_to('PROFILE-RECOVERY-FEES-2026-10-18-002:adhesive:'||p.sku,'UTF8')),'hex'),pr.id,(SELECT id FROM products WHERE sku='INS006'),'packaging',1,'unit','per_finished_unit','{"reference":"PROFILE-RECOVERY-FEES-2026-10-18-002","decision":"one adhesive per sold package"}'::jsonb FROM production_profiles pr JOIN products p ON p.id=pr.product_id WHERE pr.recipe_version_id=(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002');
INSERT INTO production_profile_components(source_id,source_hash,production_profile_id,product_id,role,quantity,unit,quantity_basis,source_payload) SELECT 'PROFILE-RECOVERY-FEES-2026-10-18-002:coating:'||p.sku,encode(sha256(convert_to('PROFILE-RECOVERY-FEES-2026-10-18-002:coating:'||p.sku,'UTF8')),'hex'),pr.id,(SELECT id FROM products WHERE sku='INS019'),'coating',CASE p.sku WHEN 'PROD001' THEN 50 ELSE 200 END,'g','per_finished_unit','{"reference":"PROFILE-RECOVERY-FEES-2026-10-18-002","decision":"approximately 50g coating per bombom; four direct in kit"}'::jsonb FROM production_profiles pr JOIN products p ON p.id=pr.product_id WHERE pr.recipe_version_id=(SELECT id FROM recipe_versions WHERE source_id='RECIPE-BASE-002') AND p.sku IN ('PROD001','PROD017');
INSERT INTO management_scenario_history(scenario_id,revision,scenario_version,event,actor_auth_user_id,reason,snapshot) SELECT id,revision,version,'archived','codex:authorized-hml-release','PROFILE-RECOVERY-FEES-2026-10-18-002',jsonb_build_object('scenario',to_jsonb(s),'mix',(SELECT jsonb_agg(to_jsonb(m) ORDER BY product_id) FROM management_scenario_mix m WHERE m.scenario_id=s.id)) FROM management_scenarios s WHERE id=1;
INSERT INTO management_scenarios(scenario_key,version,revision,supersedes_scenario_id,name,description,status,effective_on,monthly_profit_goal,fixed_monthly_costs,sales_days_per_month,weeks_per_month,minimum_margin_bps,fee_tax_reserve_bps,created_by_auth_user_id,updated_by_auth_user_id,replacement_reason) SELECT scenario_key,2,1,id,'Meta conjunta R$ 10 mil — mix orientativo','Meta conjunta R$ 10.000 de lucro: todas as vendas contam no resultado. Mix orientativo de brownies/bombons/kits, sem cotas obrigatórias por produto. Bordinhas vendidas contam como aproveitamento adicional, sem volume mínimo presumido. Fixos R$ 2.288 incluem MO R$ 600 (4 diárias de R$ 150), energia e MEI R$ 88. Receita 8 ovos/850 g frios. Custos físicos do workbook sem somar MO/energia novamente. Base antes das taxas; comparar débito 1,43%, crédito 3,36% e Pix R$ 0,49/transação, sem mistura presumida. Plano-base: 63.336 receitas equivalentes; faixa informada 56–64/mês. Rendimento e custos realizados dependem dos apontamentos e compras. Bordinhas 100 g/R$ 6; bombom cerca de 50 g de cobertura; kit4 sem embalagem interna. Custos planejados em 3 casas; FIFO preserva frações exatas.','draft','2026-10-18',10000,2288,20,4,7000,0,'codex:authorized-hml-release','codex:authorized-hml-release','Meta conjunta, custos revistos e Bordinhas conforme aproveitamento real.' FROM management_scenarios WHERE id=1;
